// ---------- time zone -> city ----------

let tzLookupMap = null, zoneTop = null;
const offsetCache = new Map();

function tzLookup(name) {
	if (!tzLookupMap) {
		tzLookupMap = new Map();
		for (const a in TZ_ALIAS) tzLookupMap.set(a.toLowerCase(), TZS.indexOf(TZ_ALIAS[a]));
		for (let i = 0; i < TZS.length; i++) tzLookupMap.set(TZS[i].toLowerCase(), i);
	}
	const i = tzLookupMap.get(name.toLowerCase());
	return i === undefined ? -1 : i;
}

function topCity(zi) {
	if (!zoneTop) {
		zoneTop = new Int32Array(TZS.length).fill(-1);
		for (let i = CITIES.length - 1; i >= 0; i--) zoneTop[CITIES[i][5]] = i;
	}
	return zoneTop[zi];
}

// [offset now, offset on 15 January, offset on 15 July] in minutes east of UTC; throws for an unknown zone.
function offsets(zone) {
	let o = offsetCache.get(zone);
	if (!o) {
		const f = new Intl.DateTimeFormat('en-US', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' });
		const at = t => {
			const p = {};
			for (const x of f.formatToParts(t)) p[x.type] = +x.value;
			return Math.round((Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute) - t) / 60000);
		};
		const now = Math.floor(Date.now() / 60000) * 60000, y = new Date(now).getUTCFullYear();
		o = [at(now), at(Date.UTC(y, 0, 15)), at(Date.UTC(y, 6, 15))];
		offsetCache.set(zone, o);
	}
	return o;
}

// For a zone with no city of its own: the most populous city (in `country`, when given) whose zone
// keeps the same time now and in both seasons, preferring the same tz area (America/, Europe/ ...);
// failing that, the same offset now; failing that, the nearest offset now, same area first (for a
// zone such as Australia/Eucla, +8:45, that no city shares). -1 if `country` has no city.
function byOffset(name, country) {
	const want = offsets(name), area = name.split('/')[0];
	let sameRules = -1, sameNow = -1, nearest = -1, nearestKey = Infinity;
	for (let i = 0; i < CITIES.length; i++) {
		if (country && CITIES[i][2] !== country) continue;
		const z = TZS[CITIES[i][5]], o = offsets(z), sameArea = z.split('/')[0] === area;
		if (o[0] === want[0]) {
			if (o[1] === want[1] && o[2] === want[2]) {
				if (sameArea) return i;
				if (sameRules < 0) sameRules = i;
			} else if (sameNow < 0) sameNow = i;
		} else {
			const key = Math.abs(o[0] - want[0]) + (sameArea ? 0 : 100000);
			if (key < nearestKey) { nearestKey = key; nearest = i; }
		}
	}
	return sameRules >= 0 ? sameRules : sameNow >= 0 ? sameNow : nearest;
}

/**
 * Index into CITIES of the most populous city in IANA zone `tz` (aliases accepted). A zone with no
 * city of its own falls back to a city in the same country (tzdata zone.tab) keeping the same time,
 * then to the most populous city anywhere keeping the same time (see byOffset); an empty or unknown
 * zone gives London. Never throws.
 */
export function cityForTimeZone(tz) {
	try {
		const name = typeof tz === 'string' ? tz.trim() : '';
		if (!name) return LONDON;
		if (ZONE_CITY[name] !== undefined) return ZONE_CITY[name];
		let zi = tzLookup(name), canon = name;
		if (zi < 0) {
			// The browser may know the zone under another spelling (e.g. Asia/Calcutta for Asia/Kolkata).
			canon = new Intl.DateTimeFormat('en-US', { timeZone: name }).resolvedOptions().timeZone;
			if (ZONE_CITY[canon] !== undefined) return ZONE_CITY[canon];
			zi = tzLookup(canon);
		}
		let c = zi >= 0 ? topCity(zi) : -1;
		const ci = ZONE_COUNTRY[name] ?? ZONE_COUNTRY[canon];
		if (c < 0 && ci !== undefined) c = byOffset(name, COUNTRIES[ci]);
		if (c < 0) c = byOffset(name);
		return c >= 0 ? c : LONDON;
	} catch (e) {
		return LONDON;
	}
}

